insert into media (account_id, product_id, kind, storage_path, caption, approved)
select a.id, p.id, 'product', src.f, src.n, true
from src
join accounts a on a.import_code = src.s
join products p on p.supplier_id = a.id and p.name = src.n
where not exists (
  select 1 from media m where m.product_id = p.id and m.storage_path = src.f
);

commit;
